#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
GMAIL_DIR="${HOME}/.gmail-mcp"
KEYS_PATH="${GMAIL_DIR}/gcp-oauth.keys.json"
CREDS_PATH="${GMAIL_DIR}/credentials.json"

banner "Email MCP read-only (Privat-Gmail + Brüggen-Mail)"

stage "Prepare ~/.gmail-mcp"
say "Tokens stay local. Never commit them to Git."
mkdir -p "$GMAIL_DIR"
chmod 700 "$GMAIL_DIR"
note "Directory: $GMAIL_DIR"
pause "Directory ready — press Enter"

stage "Google Cloud — OAuth Desktop client"
say "Create OAuth credentials for your private Gmail (read-only later)."
open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
step "Enable the Gmail API for a Google Cloud project (create one if needed)."
pause "Gmail API enabled — press Enter"
open_url "https://console.cloud.google.com/apis/credentials"
step "Configure OAuth consent screen if prompted (External + your Gmail as test user is fine for personal use)."
step "Create Credentials → OAuth client ID → Application type: Desktop app."
step "Click Download JSON (the whole file). Do NOT paste only the Client ID string."
say "Save/rename the downloaded file to exactly:"
note "$KEYS_PATH"
pause "After the full JSON file is at that path, press Enter"
if [[ ! -f "$KEYS_PATH" ]]; then
  warn "File missing: $KEYS_PATH"
  ask KEYS_SRC "Paste absolute path to the downloaded OAuth JSON:"
  cp "$KEYS_SRC" "$KEYS_PATH"
  chmod 600 "$KEYS_PATH"
fi
[[ -f "$KEYS_PATH" ]] || { warn "Still missing $KEYS_PATH — abort."; exit 1; }
if ! python3 - "$KEYS_PATH" <<'PY'
import json, sys
from pathlib import Path
p = Path(sys.argv[1])
try:
    data = json.loads(p.read_text())
except Exception as e:
    print(f"INVALID JSON: {e}")
    sys.exit(1)
block = data.get("installed") or data.get("web")
if not isinstance(block, dict):
    print("INVALID: expected top-level key 'installed' (Desktop) or 'web'")
    sys.exit(1)
for req in ("client_id", "client_secret"):
    if not block.get(req):
        print(f"INVALID: missing {req} inside OAuth client block")
        sys.exit(1)
print("OK")
PY
then
  warn "gcp-oauth.keys.json is not a valid Google Desktop OAuth download."
  say "Re-download from Google Cloud → Credentials → your OAuth client → Download JSON."
  say "Typical content starts with { \"installed\": { \"client_id\": ... } }"
  exit 1
fi
chmod 600 "$KEYS_PATH"
say "OAuth keys present and look valid."

stage "Gmail auth with gmail.readonly"
say "Browser consent opens; approve only read access for your private Gmail."
warn "Port 3000 is often taken (e.g. OrbStack). Auth uses a free localhost port."
FREE_PORT=""
for p in 3456 8765 18080 48080; do
  if ! lsof -iTCP:"$p" -sTCP:LISTEN >/dev/null 2>&1; then FREE_PORT=$p; break; fi
done
[[ -n "$FREE_PORT" ]] || { warn "No free callback port found."; exit 1; }
CALLBACK="http://localhost:${FREE_PORT}/oauth2callback"
step "Run auth with callback $CALLBACK"
confirm "Start Gmail auth now?"
( cd "$GMAIL_DIR" && npx -y @artymclabin/gmail-mcp auth --scopes=gmail.readonly "$CALLBACK" )
if [[ -f "$CREDS_PATH" ]]; then
  chmod 600 "$CREDS_PATH"
  say "Credentials saved: $CREDS_PATH"
else
  warn "credentials.json not found after auth — check the auth output."
fi

stage "Microsoft 365 mail login (Brüggen)"
say "Login as sfleig@brueggen-engineering.de. Read-only mail tools only."
warn "If Microsoft asks for admin consent (Mail.Read), stop and ask tenant admin — do not bypass."
step "Command uses --org-mode --read-only + enabled-tools list/get/download"
READ_TOOLS='list-mail-messages|list-mail-folders|list-mail-child-folders|list-mail-folder-messages|get-mail-message|list-mail-attachments|get-mail-message-mime|download-bytes|get-mailbox-settings|list-outlook-categories|get-mail-tips'
confirm "Start ms365 device/browser login now?"
npx -y @softeria/ms-365-mcp-server \
  --org-mode \
  --read-only \
  --expected-username sfleig@brueggen-engineering.de \
  --enabled-tools "$READ_TOOLS" \
  --login
npx -y @softeria/ms-365-mcp-server \
  --org-mode \
  --read-only \
  --expected-username sfleig@brueggen-engineering.de \
  --enabled-tools "$READ_TOOLS" \
  --verify-login || warn "verify-login failed — likely admin consent still required."

stage "Reload Cursor MCP"
say "Cursor Host config already has servers gmail-mcp and ms365-mail in ~/.cursor/mcp.json"
step "Reload MCP / restart Cursor agent session so the new servers load."
step "Smoke: search one non-sensitive private mail; list Brüggen inbox folders only (no Bewerber bodies in chat/logs)."
note "Doc: ~/Projects/03_HAI/docs/EMAIL_MCP_READ_PATH.md"
pause "After reload, press Enter to finish"

finish
